  Ltac finp_done :=
    lazymatch goal with |- evt _ _ (MS ?R ?Fx (Z_to_bv 64 ?pc) ?fcx _ _ _) =>
      let r := rv_of R in apply evt_done; unhide_post; exists pc, r, Fx, fcx;
      split; [reflexivity|];
      split; [first [left; reflexivity | right; left; reflexivity | right; right; left; reflexivity | right; right; right; reflexivity]|];
      split; [assumption|]; rv_cbv; repeat (split; [reflexivity|]); reflexivity end.
  Ltac tbl_read :=
    match goal with |- evt _ _ (MS ?R _ _ _ _ ?mm _) => let t := rv_reg R 10 in
      lazymatch t with Z_to_bv 64 (86432 + ?idx * Z.pow 2 3) =>
        replace t with (Z_to_bv 64 (POW10U_TBL + 8 * idx)) by (unfold POW10U_TBL; f_equal; lia);
        let RD := fresh "RD" in
        match goal with MIx : mem_inv _ mm |- _ => pose proof (pow10u_read mm idx MIx ltac:(lia)) as RD end
